INSERT INTO app_private.coaching_models (model_key, name_i18n, focus_i18n, limitation_i18n, source_title, source_url, source_kind, topic_tags) VALUES
  ('grow_v1', '{"en":"GROW","ru":"GROW — Цель и действие","es":"GROW — Meta y acción"}'::jsonb, '{"en":"Move from an owned goal and current reality to options and a realistic next step.","ru":"От своей цели и текущей реальности — к вариантам и посильному шагу.","es":"Pasar de una meta propia y la situación actual a opciones y un primer paso posible."}'::jsonb, '{"en":"A flexible structure, not a diagnosis or guarantee of results.","ru":"Гибкая структура, не диагноз и не обещание результата.","es":"Es una estructura flexible, no un diagnóstico ni una garantía."}'::jsonb, 'Using the GROW Model for Coaching and Mentoring · Canada School of Public Service', 'https://www.csps-efpc.gc.ca/tools/jobaids/grow-model-eng.aspx', 'institutional', ARRAY['goal','decision','business','career','money']::text[]),
  ('tgrow_v1', '{"en":"TGROW","ru":"TGROW — Сначала тема","es":"TGROW — Primero el tema"}'::jsonb, '{"en":"Clarify an unclear concern before deciding what outcome to pursue.","ru":"Прояснить расплывчатый запрос до постановки цели.","es":"Aclarar una inquietud antes de fijar una meta."}'::jsonb, '{"en":"The topic must be chosen by the client, not inferred from psychological scores.","ru":"Тему выбирает клиент; нельзя выводить её из психологических баллов.","es":"El tema lo elige la persona, no se deduce de puntuaciones psicológicas."}'::jsonb, 'Coaching for health: holding the curtains so patients can change · PMC', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC3662442/', 'research', ARRAY['unclear','decision','transition','goal','career']::text[]),
  ('oskar_v1', '{"en":"OSKAR","ru":"OSKAR — Опора на ресурсы","es":"OSKAR — Recursos y avances"}'::jsonb, '{"en":"Find useful strengths, name progress and define the next small improvement.","ru":"Замечать сильные стороны, прогресс и ближайшее улучшение.","es":"Reconocer fortalezas, progreso y el siguiente avance pequeño."}'::jsonb, '{"en":"A self-rating is a private reflection aid, never a validated clinical score.","ru":"Личная шкала — только самоотчёт, не клинический показатель.","es":"La escala es solo reflexión personal, no una puntuación clínica."}'::jsonb, 'OSKAR coaching · Mark McKergow and Paul Z Jackson', 'https://sfwork.com/oskar-coaching', 'original', ARRAY['stuck','confidence','motivation','relationships','growth']::text[]),
  ('clear_v1', '{"en":"CLEAR","ru":"CLEAR — Осмысленный разговор","es":"CLEAR — Conversación reflexiva"}'::jsonb, '{"en":"Begin with an agreement, listen, explore and review actions.","ru":"Договориться о фокусе, услышать, исследовать и подвести итог.","es":"Acordar el enfoque, escuchar, explorar y revisar acciones."}'::jsonb, '{"en":"Digital prompts cannot replace an attentive human coach in serious interpersonal conflict.","ru":"Цифровые вопросы не заменяют внимательного специалиста в серьёзном конфликте.","es":"Las preguntas digitales no sustituyen a un profesional en un conflicto grave."}'::jsonb, 'Transformational Coaching — The CLEAR model · Leadership Centre', 'https://www.leadershipcentre.org.uk/artofchangemaking/theory/transformational-coaching-the-clear-model/', 'institutional', ARRAY['relationships','conflict','communication','transition','leadership']::text[]),
  ('fuel_v1', '{"en":"FUEL","ru":"FUEL — Развитие эффективности","es":"FUEL — Desarrollo profesional"}'::jsonb, '{"en":"Frame a work conversation, understand today, explore the desired state and make a plan.","ru":"Определить рабочую тему, увидеть настоящее и желаемое, составить план.","es":"Enmarcar una conversación laboral, explorar el presente, el futuro y un plan."}'::jsonb, '{"en":"Do not use as a substitute for employment, legal or financial advice.","ru":"Не заменяет кадровую, правовую или финансовую консультацию.","es":"No sustituye la asesoría laboral, legal o financiera."}'::jsonb, 'FUEL Coaching Framework · NYU Coaching for Leadership', 'https://wp.nyu.edu/coaching/tools/fuel-model/', 'institutional', ARRAY['leadership','career','business','communication','productivity']::text[]),
  ('solution_focus_v1', '{"en":"Solution-Focused Coaching","ru":"Коучинг, ориентированный на решение","es":"Coaching centrado en soluciones"}'::jsonb, '{"en":"Look for a preferred future, exceptions and signs of small useful change.","ru":"Искать желаемое будущее, исключения и небольшие признаки перемен.","es":"Explorar un futuro preferido, excepciones y cambios pequeños."}'::jsonb, '{"en":"This is a coaching adaptation; it is not solution-focused psychotherapy.","ru":"Это коучинговая адаптация, не психотерапия.","es":"Es una adaptación de coaching, no psicoterapia."}'::jsonb, 'Solution-focused approaches: conceptual literature review · PMC', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10098109/', 'research', ARRAY['stuck','confidence','motivation','relationships','transition']::text[]),
  ('woop_v1', '{"en":"WOOP","ru":"WOOP — Намерение и препятствие","es":"WOOP — Deseo y obstáculo"}'::jsonb, '{"en":"Clarify a doable wish, desired outcome, inner obstacle and a specific if–then plan.","ru":"Выбрать посильное желание, результат, внутреннее препятствие и план «если — то».","es":"Elegir un deseo alcanzable, su resultado, obstáculo interno y un plan «si — entonces»."}'::jsonb, '{"en":"Closed choices alone do not complete the tested WOOP method. The person needs to formulate a specific inner obstacle and their own if–then action.","ru":"Одних готовых вариантов недостаточно для полноценной WOOP: нужен собственный конкретный план «если — то».","es":"Las opciones cerradas no completan el método WOOP: se necesita un plan «si — entonces» propio y concreto."}'::jsonb, 'WOOP practice · official WOOP My Life', 'https://woopmylife.org/en/practice', 'original', ARRAY['habits','procrastination','motivation','goal','productivity']::text[]),
  ('appreciative_5d_v1', '{"en":"Appreciative Inquiry · 5D","ru":"Appreciative Inquiry — 5D","es":"Indagación Apreciativa · 5D"}'::jsonb, '{"en":"Use strengths and vivid examples to co-design a positive future.","ru":"Через сильные стороны и удачные примеры проектировать будущее.","es":"Utilizar fortalezas y ejemplos positivos para diseñar el futuro."}'::jsonb, '{"en":"Originally used in teams and organizations; the personal session is an explicit adaptation, not a standardized test.","ru":"Исходно для команд и организаций; индивидуальная сессия — адаптация, не тест.","es":"Se originó para equipos y organizaciones; la sesión personal es una adaptación, no una prueba."}'::jsonb, 'Frequently Asked Questions · Center for Appreciative Inquiry', 'https://centerforappreciativeinquiry.net/faqs/', 'practitioner', ARRAY['transition','growth','leadership','business','confidence']::text[])
INSERT INTO app_private.coaching_answer_sets (answer_set_key, choices) VALUES
  ('focus_v1', '[{"id":"clarity","label":{"en":"Clarity","ru":"Ясность","es":"Claridad"}},{"id":"choice","label":{"en":"A decision","ru":"Решение","es":"Una decisión"}},{"id":"conversation","label":{"en":"A conversation","ru":"Разговор","es":"Una conversación"}},{"id":"action","label":{"en":"A practical action","ru":"Действие","es":"Una acción concreta"}},{"id":"not_sure","label":{"en":"I am not sure yet","ru":"Пока не знаю","es":"Aún no sé"}}]'::jsonb),
  ('scope_v1', '[{"id":"work","label":{"en":"Work or business","ru":"Работа или бизнес","es":"Trabajo o negocio"}},{"id":"relationships","label":{"en":"Relationships","ru":"Отношения","es":"Relaciones"}},{"id":"personal","label":{"en":"Personal goals","ru":"Личные цели","es":"Metas personales"}},{"id":"team","label":{"en":"Team or community","ru":"Команда или сообщество","es":"Equipo o comunidad"}},{"id":"unsure","label":{"en":"Not sure","ru":"Не знаю","es":"No sé"}}]'::jsonb),
  ('sign_v1', '[{"id":"visible_result","label":{"en":"A visible result","ru":"Заметный результат","es":"Un resultado visible"}},{"id":"greater_clarity","label":{"en":"More clarity","ru":"Больше ясности","es":"Más claridad"}},{"id":"better_talk","label":{"en":"A better conversation","ru":"Лучший разговор","es":"Una mejor conversación"}},{"id":"repeatable_step","label":{"en":"A repeatable action","ru":"Повторяемое действие","es":"Una acción repetible"}},{"id":"unsure","label":{"en":"Not sure yet","ru":"Пока не знаю","es":"Aún no sé"}}]'::jsonb),
  ('position_v1', '[{"id":"not_started","label":{"en":"I have not begun","ru":"Ещё не начал(а)","es":"Todavía no he empezado"}},{"id":"early","label":{"en":"I have taken a first step","ru":"Сделал(а) первый шаг","es":"Ya di el primer paso"}},{"id":"in_progress","label":{"en":"I am making some progress","ru":"Есть некоторое продвижение","es":"Estoy avanzando"}},{"id":"stuck","label":{"en":"I feel stuck","ru":"Чувствую, что застрял(а)","es":"Siento un bloqueo"}},{"id":"uncertain","label":{"en":"Hard to tell","ru":"Трудно оценить","es":"Es difícil saberlo"}}]'::jsonb),
  ('strategy_v1', '[{"id":"small_action","label":{"en":"Try one small action","ru":"Попробовать небольшой шаг","es":"Probar una pequeña acción"}},{"id":"ask","label":{"en":"Ask someone for help","ru":"Попросить помощи","es":"Pedir ayuda"}},{"id":"learn","label":{"en":"Gather information","ru":"Собрать информацию","es":"Recopilar información"}},{"id":"reframe","label":{"en":"Change my approach","ru":"Изменить подход","es":"Cambiar mi enfoque"}},{"id":"pause","label":{"en":"Pause and reconsider","ru":"Сделать паузу","es":"Hacer una pausa"}}]'::jsonb),
  ('resource_v1', '[{"id":"experience","label":{"en":"Something that worked before","ru":"Прошлый удачный опыт","es":"Algo que funcionó antes"}},{"id":"skills","label":{"en":"My existing skills","ru":"Мои навыки","es":"Mis habilidades"}},{"id":"people","label":{"en":"Supportive people","ru":"Поддерживающие люди","es":"Personas que me apoyan"}},{"id":"time","label":{"en":"Time or space to focus","ru":"Время и внимание","es":"Tiempo para concentrarme"}},{"id":"uncertain","label":{"en":"Not identified yet","ru":"Пока не определил(а)","es":"Aún no lo identifico"}}]'::jsonb),
  ('barrier_v1', '[{"id":"time","label":{"en":"Not enough time","ru":"Недостаток времени","es":"Falta de tiempo"}},{"id":"clarity","label":{"en":"Unclear next step","ru":"Неясный следующий шаг","es":"Falta de claridad"}},{"id":"confidence","label":{"en":"Doubt or hesitation","ru":"Сомнение или колебание","es":"Dudas o vacilación"}},{"id":"resources","label":{"en":"Limited practical resources","ru":"Не хватает ресурсов","es":"Recursos limitados"}},{"id":"other","label":{"en":"Something else / uncertain","ru":"Другое или пока неясно","es":"Otra cosa o no lo sé"}}]'::jsonb),
  ('timing_v1', '[{"id":"today","label":{"en":"Today","ru":"Сегодня","es":"Hoy"}},{"id":"week","label":{"en":"Within seven days","ru":"В течение недели","es":"En siete días"}},{"id":"month","label":{"en":"Within a month","ru":"В течение месяца","es":"En un mes"}},{"id":"later","label":{"en":"I need to decide later","ru":"Решу позже","es":"Lo decidiré después"}}]'::jsonb),
  ('progress_v1', '[{"id":"better","label":{"en":"A little better","ru":"Немного лучше","es":"Un poco mejor"}},{"id":"same","label":{"en":"About the same","ru":"Примерно так же","es":"Más o menos igual"}},{"id":"less","label":{"en":"Less than before","ru":"Хуже, чем раньше","es":"Menos que antes"}},{"id":"unknown","label":{"en":"Not enough information","ru":"Недостаточно информации","es":"No hay suficiente información"}}]'::jsonb),
  ('trigger_v1', '[{"id":"delay","label":{"en":"Putting it off","ru":"Откладываю","es":"Pospongo las cosas"}},{"id":"distraction","label":{"en":"Distractions","ru":"Отвлечения","es":"Distracciones"}},{"id":"doubt","label":{"en":"Self-doubt","ru":"Сомнения","es":"Dudas"}},{"id":"fatigue","label":{"en":"Low energy","ru":"Мало сил","es":"Poca energía"}},{"id":"unclear","label":{"en":"Unclear situation","ru":"Неясная ситуация","es":"Situación poco clara"}}]'::jsonb),
  ('next_v1', '[{"id":"two_minutes","label":{"en":"Start for two minutes","ru":"Начать с двух минут","es":"Empezar dos minutos"}},{"id":"schedule","label":{"en":"Put it on my calendar","ru":"Запланировать время","es":"Agendarlo"}},{"id":"ask","label":{"en":"Contact someone relevant","ru":"Обратиться к человеку","es":"Contactar a alguien"}},{"id":"prepare","label":{"en":"Prepare one concrete item","ru":"Подготовить одну вещь","es":"Preparar una cosa"}},{"id":"pause","label":{"en":"No action yet / reconsider","ru":"Пока без шага","es":"Por ahora, esperar"}}]'::jsonb),
  ('change_v1', '[{"id":"routine","label":{"en":"My daily routine","ru":"Повседневные привычки","es":"Mi rutina diaria"}},{"id":"process","label":{"en":"A process or system","ru":"Процесс или система","es":"Un proceso o sistema"}},{"id":"team","label":{"en":"A relationship or team","ru":"Отношения или команда","es":"Una relación o equipo"}},{"id":"goal","label":{"en":"The goal itself","ru":"Сама цель","es":"La meta en sí"}},{"id":"unsure","label":{"en":"Not sure","ru":"Пока не знаю","es":"Todavía no lo sé"}}]'::jsonb),
  ('review_v1', '[{"id":"useful","label":{"en":"Useful and clear","ru":"Полезно и понятно","es":"Útil y claro"}},{"id":"partly","label":{"en":"Somewhat useful","ru":"Отчасти полезно","es":"Algo útil"}},{"id":"more_time","label":{"en":"I want more reflection","ru":"Нужна ещё пауза","es":"Necesito reflexionar más"}},{"id":"none","label":{"en":"Not useful yet","ru":"Пока не помогло","es":"Aún no me ha servido"}}]'::jsonb)
INSERT INTO app_private.coaching_steps (model_key, step_key, model_order, title_i18n, emphasis_i18n, key_question_i18n) VALUES
  ('grow_v1', 'frame', 1, '{"en":"Frame","ru":"Начать разговор","es":"Encuadrar"}'::jsonb, '{"en":"Agree what is worth exploring.","ru":"Определить, чему посвятить время.","es":"Acordar qué vale la pena explorar."}'::jsonb, '{"en":"What would make this conversation worthwhile to you?","ru":"Что сделает этот разговор полезным для вас?","es":"¿Qué haría útil esta conversación para ti?"}'::jsonb),
  ('grow_v1', 'goal', 2, '{"en":"Goal","ru":"Цель","es":"Meta"}'::jsonb, '{"en":"Choose an outcome you can recognize.","ru":"Выбрать узнаваемый результат.","es":"Elegir un resultado reconocible."}'::jsonb, '{"en":"What would show that you have reached your chosen goal?","ru":"По чему вы поймёте, что приблизились к своей цели?","es":"¿Qué indicaría que te acercaste a tu meta?"}'::jsonb),
  ('grow_v1', 'reality', 3, '{"en":"Reality","ru":"Реальность","es":"Realidad"}'::jsonb, '{"en":"Describe what exists, without judgment.","ru":"Замечать факты без самооценки.","es":"Observar los hechos sin juzgar."}'::jsonb, '{"en":"What is already happening in this situation?","ru":"Что уже происходит в этой ситуации?","es":"¿Qué está ocurriendo ya en esta situación?"}'::jsonb),
  ('grow_v1', 'options', 4, '{"en":"Options","ru":"Возможности","es":"Opciones"}'::jsonb, '{"en":"Explore alternatives before selecting one.","ru":"Сначала увидеть варианты, затем выбрать.","es":"Explorar opciones antes de elegir."}'::jsonb, '{"en":"What alternatives are still available to you?","ru":"Какие варианты у вас ещё есть?","es":"¿Qué alternativas todavía tienes?"}'::jsonb),
  ('grow_v1', 'will', 5, '{"en":"Way forward","ru":"Следующий шаг","es":"Próximo paso"}'::jsonb, '{"en":"Choose one owned and feasible action.","ru":"Выбрать один посильный шаг.","es":"Elegir una acción viable y propia."}'::jsonb, '{"en":"What one step will you take, and what would make it possible?","ru":"Какой один шаг вы готовы сделать и что поможет?","es":"¿Qué único paso darás y qué lo facilitaría?"}'::jsonb),
  ('grow_v1', 'review', 6, '{"en":"Review","ru":"Итог","es":"Revisión"}'::jsonb, '{"en":"Notice learning without forced optimism.","ru":"Оценить пользу без требования быть позитивным.","es":"Reconocer lo aprendido sin forzar optimismo."}'::jsonb, '{"en":"What will you take away from this conversation?","ru":"Что вы унесёте из этого разговора?","es":"¿Qué te llevas de esta conversación?"}'::jsonb),
  ('tgrow_v1', 'topic', 1, '{"en":"Topic","ru":"Тема","es":"Tema"}'::jsonb, '{"en":"Name the focus before the outcome.","ru":"Сначала выбрать тему.","es":"Primero elegir el tema."}'::jsonb, '{"en":"Which part of your situation deserves attention first?","ru":"Какой части ситуации стоит уделить внимание сначала?","es":"¿Qué parte de tu situación merece atención primero?"}'::jsonb),
  ('tgrow_v1', 'goal', 2, '{"en":"Goal","ru":"Цель","es":"Meta"}'::jsonb, '{"en":"Identify the result for this theme.","ru":"Определить желаемое изменение.","es":"Identificar el cambio deseado."}'::jsonb, '{"en":"What useful change would be enough for today?","ru":"Какого изменения было бы достаточно на сегодня?","es":"¿Qué cambio útil sería suficiente por hoy?"}'::jsonb),
  ('tgrow_v1', 'reality', 3, '{"en":"Reality","ru":"Сейчас","es":"Realidad"}'::jsonb, '{"en":"Look at the actual starting point.","ru":"Увидеть настоящую отправную точку.","es":"Ver el verdadero punto de partida."}'::jsonb, '{"en":"What is the current state of this particular issue?","ru":"Какова текущая ситуация именно по этой теме?","es":"¿Cuál es la situación actual sobre este tema?"}'::jsonb),
  ('tgrow_v1', 'options', 4, '{"en":"Options","ru":"Варианты","es":"Opciones"}'::jsonb, '{"en":"Explore choices without rushing.","ru":"Собрать варианты без спешки.","es":"Explorar opciones sin apresurarse."}'::jsonb, '{"en":"What else might move this topic forward?","ru":"Что ещё могло бы помочь продвижению?","es":"¿Qué más podría impulsar este tema?"}'::jsonb),
  ('tgrow_v1', 'will', 5, '{"en":"Commitment","ru":"Решение","es":"Compromiso"}'::jsonb, '{"en":"Choose timing you control.","ru":"Выбрать управляемый срок.","es":"Elegir un plazo bajo tu control."}'::jsonb, '{"en":"When are you willing to revisit this action?","ru":"Когда вы готовы вернуться к этому действию?","es":"¿Cuándo estás dispuesto a retomar esta acción?"}'::jsonb),
  ('oskar_v1', 'outcome', 1, '{"en":"Outcome","ru":"Результат","es":"Resultado"}'::jsonb, '{"en":"Picture a realistic preferred outcome.","ru":"Увидеть желаемый реалистичный результат.","es":"Imaginar un resultado preferido y realista."}'::jsonb, '{"en":"What would tell you that things are moving in a useful direction?","ru":"По чему вы заметите движение в полезную сторону?","es":"¿Qué te indicaría que vas en una dirección útil?"}'::jsonb),
  ('oskar_v1', 'scaling', 2, '{"en":"Scaling","ru":"Шкала","es":"Escala"}'::jsonb, '{"en":"Locate yourself on your own 0–10 scale.","ru":"Отметить субъективное положение от 0 до 10.","es":"Situarte en tu propia escala del 0 al 10."}'::jsonb, '{"en":"If ten is your preferred outcome, where are you today from zero to ten?","ru":"Если 10 — желаемый результат, где вы сейчас от 0 до 10?","es":"Si diez es el resultado deseado, ¿dónde estás hoy del cero al diez?"}'::jsonb),
  ('oskar_v1', 'knowhow', 3, '{"en":"Know-how","ru":"Ресурсы","es":"Recursos"}'::jsonb, '{"en":"Identify what already helps.","ru":"Найти то, что уже помогает.","es":"Identificar lo que ya ayuda."}'::jsonb, '{"en":"How have you managed even a small part of this before?","ru":"Благодаря чему у вас раньше получалось хотя бы немного?","es":"¿Cómo lograste antes aunque fuera una pequeña parte?"}'::jsonb),
  ('oskar_v1', 'affirm', 4, '{"en":"Affirm and act","ru":"Поддержка и шаг","es":"Reconocer y actuar"}'::jsonb, '{"en":"Recognize effort and pick an action.","ru":"Признать усилия и выбрать шаг.","es":"Reconocer el esfuerzo y elegir una acción."}'::jsonb, '{"en":"What is one strength you can bring into your next action?","ru":"Какую свою сильную сторону можно использовать в следующем шаге?","es":"¿Qué fortaleza puedes aportar a la siguiente acción?"}'::jsonb),
  ('oskar_v1', 'review', 5, '{"en":"Review","ru":"Проверка изменений","es":"Revisión"}'::jsonb, '{"en":"Check what genuinely changed.","ru":"Проверить, что действительно изменилось.","es":"Revisar qué cambió realmente."}'::jsonb, '{"en":"Since you began, what has improved, stayed the same or become harder?","ru":"Что стало лучше, осталось как было или усложнилось?","es":"¿Qué mejoró, siguió igual o empeoró?"}'::jsonb),
  ('clear_v1', 'contract', 1, '{"en":"Contract","ru":"Договорённость","es":"Acuerdo"}'::jsonb, '{"en":"Agree on the scope and boundaries.","ru":"Согласовать рамки разговора.","es":"Acordar el alcance y los límites."}'::jsonb, '{"en":"What would feel like a respectful outcome of this conversation?","ru":"Какой результат разговора был бы для вас уважительным?","es":"¿Qué resultado de esta conversación te parecería respetuoso?"}'::jsonb),
  ('clear_v1', 'listen', 2, '{"en":"Listen","ru":"Услышать себя","es":"Escuchar"}'::jsonb, '{"en":"Notice your account before interpreting.","ru":"Сначала заметить свой опыт.","es":"Notar tu experiencia antes de interpretarla."}'::jsonb, '{"en":"What feels most important to have acknowledged?","ru":"Что сейчас важнее всего признать в своём опыте?","es":"¿Qué es lo más importante que quieres reconocer?"}'::jsonb),
  ('clear_v1', 'explore', 3, '{"en":"Explore","ru":"Исследовать","es":"Explorar"}'::jsonb, '{"en":"Explore assumptions and context.","ru":"Исследовать обстоятельства и предположения.","es":"Explorar el contexto y las suposiciones."}'::jsonb, '{"en":"What may be complicating this situation?","ru":"Что может усложнять эту ситуацию?","es":"¿Qué podría estar complicando esta situación?"}'::jsonb),
  ('clear_v1', 'action', 4, '{"en":"Action","ru":"Действие","es":"Acción"}'::jsonb, '{"en":"Choose an ethical and respectful next step.","ru":"Выбрать уважительный следующий шаг.","es":"Elegir el siguiente paso respetuoso."}'::jsonb, '{"en":"What can you do without pressuring the other person?","ru":"Что вы можете сделать без давления на другого человека?","es":"¿Qué puedes hacer sin presionar a la otra persona?"}'::jsonb),
  ('clear_v1', 'review', 5, '{"en":"Review","ru":"Подвести итог","es":"Revisión"}'::jsonb, '{"en":"Check if the conversation served the agreed purpose.","ru":"Проверить соответствие первоначальному запросу.","es":"Comprobar si se cumplió el objetivo acordado."}'::jsonb, '{"en":"What now feels clearer or still needs care?","ru":"Что стало яснее, а что ещё требует внимания?","es":"¿Qué está más claro y qué necesita atención?"}'::jsonb),
  ('fuel_v1', 'frame', 1, '{"en":"Frame","ru":"Фокус","es":"Enmarcar"}'::jsonb, '{"en":"Define the developmental conversation.","ru":"Определить задачу развития.","es":"Definir la conversación de desarrollo."}'::jsonb, '{"en":"What work behavior or decision would you like to improve?","ru":"Какое рабочее действие или решение вы хотите улучшить?","es":"¿Qué conducta laboral o decisión quieres mejorar?"}'::jsonb),
  ('fuel_v1', 'understand', 2, '{"en":"Understand today","ru":"Понять настоящее","es":"Comprender el presente"}'::jsonb, '{"en":"Identify factors, not blame.","ru":"Увидеть факторы без обвинений.","es":"Identificar factores sin culpas."}'::jsonb, '{"en":"What is making the current pattern harder to change?","ru":"Что мешает изменить текущий способ действий?","es":"¿Qué dificulta cambiar el patrón actual?"}'::jsonb),
  ('fuel_v1', 'explore', 3, '{"en":"Desired state","ru":"Желаемое состояние","es":"Estado deseado"}'::jsonb, '{"en":"Clarify observable improvement.","ru":"Уточнить наблюдаемое улучшение.","es":"Aclarar mejoras observables."}'::jsonb, '{"en":"What would better work look like in a real situation?","ru":"Как улучшение проявится в реальной работе?","es":"¿Cómo se vería una mejora en una situación real?"}'::jsonb),
  ('fuel_v1', 'plan', 4, '{"en":"Success plan","ru":"План действий","es":"Plan de acción"}'::jsonb, '{"en":"Choose a concrete action and feedback loop.","ru":"Выбрать шаг и способ обратной связи.","es":"Elegir una acción y cómo revisar el resultado."}'::jsonb, '{"en":"What will you try, and how will you review its effect?","ru":"Что вы попробуете и как проверите эффект?","es":"¿Qué probarás y cómo revisarás su efecto?"}'::jsonb),
  ('solution_focus_v1', 'preferred', 1, '{"en":"Preferred future","ru":"Желаемое будущее","es":"Futuro deseado"}'::jsonb, '{"en":"Name what would be different rather than staying with the problem.","ru":"Описать отличие желаемого будущего от настоящего.","es":"Describir qué sería diferente en el futuro deseado."}'::jsonb, '{"en":"If this becomes a little easier, what might you notice first?","ru":"Если станет немного легче, что вы заметите первым?","es":"Si esto se vuelve un poco más fácil, ¿qué notarías primero?"}'::jsonb),
  ('solution_focus_v1', 'exceptions', 2, '{"en":"Exceptions","ru":"Исключения","es":"Excepciones"}'::jsonb, '{"en":"Notice moments when the concern is less present.","ru":"Замечать моменты, когда трудность меньше.","es":"Notar momentos en que la dificultad pesa menos."}'::jsonb, '{"en":"When has even a small part of this been easier?","ru":"Когда хотя бы небольшая часть давалась легче?","es":"¿Cuándo fue esto aunque fuera un poco más fácil?"}'::jsonb),
  ('solution_focus_v1', 'scale', 3, '{"en":"Progress scale","ru":"Шкала изменений","es":"Escala de progreso"}'::jsonb, '{"en":"Use a self-chosen number as a conversation aid.","ru":"Число как инструмент наблюдения, не показатель здоровья.","es":"Usar un número propio para reflexionar, no para medir salud."}'::jsonb, '{"en":"Between zero and ten, how close does your preferred future feel today?","ru":"От 0 до 10: насколько близким кажется желаемое будущее?","es":"Del cero al diez, ¿qué tan cercano sientes ese futuro?"}'::jsonb),
  ('solution_focus_v1', 'resources', 4, '{"en":"What''s working","ru":"Что работает","es":"Lo que funciona"}'::jsonb, '{"en":"Build on existing capabilities.","ru":"Опирайтесь на доступные способности.","es":"Apóyate en capacidades existentes."}'::jsonb, '{"en":"What do you already know how to do that moves things forward?","ru":"Что вы уже умеете делать, чтобы продвигаться?","es":"¿Qué sabes hacer ya que te permite avanzar?"}'::jsonb),
  ('solution_focus_v1', 'step', 5, '{"en":"Small next step","ru":"Маленький шаг","es":"Paso pequeño"}'::jsonb, '{"en":"Choose a client-owned achievable experiment.","ru":"Выбрать реалистичный эксперимент.","es":"Elegir un experimento realizable y propio."}'::jsonb, '{"en":"What small difference are you ready to try this week?","ru":"Какое небольшое изменение готовы попробовать на этой неделе?","es":"¿Qué pequeño cambio estás dispuesto a probar esta semana?"}'::jsonb),
  ('woop_v1', 'wish', 1, '{"en":"Wish","ru":"Желание","es":"Deseo"}'::jsonb, '{"en":"Choose one meaningful and feasible wish.","ru":"Одно значимое и посильное желание.","es":"Elegir un deseo importante y viable."}'::jsonb, '{"en":"What is the single wish you genuinely want to work on now?","ru":"Какое одно желание вы действительно хотите осуществлять сейчас?","es":"¿Cuál es el único deseo en el que quieres trabajar ahora?"}'::jsonb),
  ('woop_v1', 'outcome', 2, '{"en":"Outcome","ru":"Результат","es":"Resultado"}'::jsonb, '{"en":"Connect with the best meaningful result.","ru":"Представить лучший значимый результат.","es":"Conectar con el mejor resultado significativo."}'::jsonb, '{"en":"What would be the most rewarding part of fulfilling it?","ru":"Что будет самым ценным в исполнении желания?","es":"¿Qué sería lo más valioso de lograrlo?"}'::jsonb),
  ('woop_v1', 'obstacle', 3, '{"en":"Inner obstacle","ru":"Внутреннее препятствие","es":"Obstáculo interno"}'::jsonb, '{"en":"Identify the most relevant internal obstacle without judgment.","ru":"Увидеть главное внутреннее препятствие без осуждения.","es":"Reconocer sin juzgar el principal obstáculo interno."}'::jsonb, '{"en":"What response within you most often interrupts progress?","ru":"Какая ваша реакция чаще всего мешает продвижению?","es":"¿Qué reacción interna interrumpe más tu avance?"}'::jsonb),
  ('woop_v1', 'plan', 4, '{"en":"If–then plan","ru":"План «если — то»","es":"Plan «si — entonces»"}'::jsonb, '{"en":"Create one personal trigger-action pairing.","ru":"Связать одну конкретную ситуацию и действие.","es":"Vincular una situación concreta con una acción propia."}'::jsonb, '{"en":"If your obstacle appears again, what one exact action will you take then?","ru":"Если препятствие появится снова, какое одно конкретное действие вы предпримете?","es":"Si el obstáculo aparece de nuevo, ¿qué acción exacta realizarás?"}'::jsonb),
  ('appreciative_5d_v1', 'define', 1, '{"en":"Define","ru":"Определить тему","es":"Definir"}'::jsonb, '{"en":"Choose a constructive inquiry focus.","ru":"Найти созидательную тему исследования.","es":"Elegir un enfoque constructivo."}'::jsonb, '{"en":"What area would you most like to see flourish?","ru":"Какую сферу вы особенно хотите развивать?","es":"¿Qué ámbito te gustaría ver florecer?"}'::jsonb),
  ('appreciative_5d_v1', 'discover', 2, '{"en":"Discover","ru":"Найти удачный опыт","es":"Descubrir"}'::jsonb, '{"en":"Notice the conditions behind your best moments.","ru":"Найти условия удачных моментов.","es":"Descubrir las condiciones de los mejores momentos."}'::jsonb, '{"en":"What conditions helped when things were going well?","ru":"Что помогало, когда дела шли удачно?","es":"¿Qué ayudó cuando las cosas salían bien?"}'::jsonb),
  ('appreciative_5d_v1', 'dream', 3, '{"en":"Dream","ru":"Вообразить","es":"Soñar"}'::jsonb, '{"en":"Imagine a meaningful preferred future.","ru":"Представить желаемое будущее.","es":"Imaginar un futuro deseado y significativo."}'::jsonb, '{"en":"What would you most notice if that strength shaped your future?","ru":"Что изменилось бы, если бы эта сила влияла на будущее?","es":"¿Qué cambiaría si esa fortaleza guiara tu futuro?"}'::jsonb),
  ('appreciative_5d_v1', 'design', 4, '{"en":"Design","ru":"Спроектировать","es":"Diseñar"}'::jsonb, '{"en":"Choose a process that supports the vision.","ru":"Наметить поддерживающую систему.","es":"Elegir un proceso que sostenga la visión."}'::jsonb, '{"en":"What in your routine, relationships or environment could support that future?","ru":"Что в привычках, отношениях или окружении поддержит такое будущее?","es":"¿Qué en tu rutina, relaciones o entorno sostendría ese futuro?"}'::jsonb),
  ('appreciative_5d_v1', 'destiny', 5, '{"en":"Deliver and learn","ru":"Воплотить и учиться","es":"Realizar y aprender"}'::jsonb, '{"en":"Try a small experiment and learn from it.","ru":"Провести небольшой эксперимент и сделать выводы.","es":"Probar un pequeño experimento y aprender."}'::jsonb, '{"en":"What small experiment could express the future you chose?","ru":"Какой небольшой эксперимент отражает выбранное будущее?","es":"¿Qué pequeño experimento expresaría el futuro elegido?"}'::jsonb)
