-- Author-reviewed original HH question wording, informed by attributed coaching frameworks.
-- No copied proprietary questionnaires. This is an educational self-coaching adaptation,
-- not a psychometric test or clinical protocol. Stable _v1 keys pin history.
BEGIN;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

-- Fail the seed transaction rather than persisting schemes with missing stages or options.
DO $quality$
BEGIN
  IF EXISTS (
    SELECT 1 FROM app_private.coaching_schemes s
    CROSS JOIN LATERAL unnest(s.step_keys) AS step_key
    LEFT JOIN app_private.coaching_steps step ON step.model_key=s.model_key AND step.step_key=step_key
    WHERE step.model_key IS NULL
  ) THEN RAISE EXCEPTION 'Coaching scheme references an unknown step'; END IF;
  IF EXISTS (
    SELECT 1 FROM app_private.coaching_answer_sets a,
      LATERAL jsonb_array_elements(a.choices) AS opt
    WHERE NOT (opt ? 'id' AND opt ? 'label'
      AND (opt->'label') ?& ARRAY['en','ru','es'])
  ) THEN RAISE EXCEPTION 'Coaching answer options require stable id and en/ru/es'; END IF;
END $quality$;
COMMIT;
